// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

/**
 * @title Counter
 * @notice Throwaway target for spike task S-06.
 *
 * The point of this contract is NOT the counter. It is `lastCaller` and
 * `bumpsBy`.
 *
 * Acceptance criterion A1 is "an XRPL testnet payment executes an arbitrary
 * call on Coston2 via a Smart Account". A bare counter cannot prove that: the
 * number goes up whether the caller was the user's PersonalAccount or the
 * operator's own EOA submitting directly. Recording `msg.sender` is what turns
 * this into evidence.
 *
 * After the spike runs, `lastCaller` MUST equal the PersonalAccount address
 * derived from the XRPL address in S-05. If it equals the operator EOA, the
 * spike has not actually proven anything and A1 has not passed.
 *
 * Delete this contract once Phase 1 begins. It is not part of the product.
 */
contract Counter {
    /// @notice Total bumps across all callers.
    uint256 public count;

    /// @notice The address that most recently called `bump`. This is the evidence.
    address public lastCaller;

    /// @notice Block timestamp of the most recent bump.
    uint256 public lastBumpedAt;

    /// @notice Per caller bump count, so one run cannot be confused with another.
    mapping(address caller => uint256 bumps) public bumpsBy;

    event Bumped(address indexed caller, uint256 indexed newCount, uint256 at);

    error AmountZero();
    error AmountTooLarge();

    /// @notice Increment by one. Returns the new total.
    function bump() external returns (uint256) {
        return _bump(1);
    }

    /// @notice Increment by `amount`. Lets the spike prove that calldata arguments survive the round trip.
    function bumpBy(uint256 amount) external returns (uint256) {
        if (amount == 0) revert AmountZero();
        if (amount > 1_000) revert AmountTooLarge();
        return _bump(amount);
    }

    function _bump(uint256 amount) private returns (uint256) {
        unchecked {
            count += amount;
            bumpsBy[msg.sender] += amount;
        }
        lastCaller = msg.sender;
        lastBumpedAt = block.timestamp;

        emit Bumped(msg.sender, count, block.timestamp);
        return count;
    }

    /// @notice Convenience read for the spike script.
    function state() external view returns (uint256 total, address caller, uint256 at) {
        return (count, lastCaller, lastBumpedAt);
    }
}
